use hawdb::{ProcessMemorySnapshot,RuntimeMemoryReservation,RuntimeTaskContext,SearchDocument,SearchOutOfCoreGenerationBuildOptions,SearchOutOfCoreGenerationWriter,SearchOutOfCoreReader,SearchProjectionDelta,SearchProjectionKind,SearchProjectionRow};
use std::{alloc::{GlobalAlloc,Layout,System},collections::BTreeMap,num::NonZeroU64,path::PathBuf,sync::atomic::{AtomicBool,AtomicUsize,Ordering},time::{Instant,SystemTime,UNIX_EPOCH}};
struct Counted;
static LIVE:AtomicUsize=AtomicUsize::new(0);
static PEAK:AtomicUsize=AtomicUsize::new(0);
fn add(n:usize){let used=LIVE.fetch_add(n,Ordering::Relaxed)+n;PEAK.fetch_max(used,Ordering::Relaxed);}
unsafe impl GlobalAlloc for Counted {
 unsafe fn alloc(&self,l:Layout)->*mut u8{let p=System.alloc(l);if !p.is_null(){add(l.size());}p}
 unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{let p=System.alloc_zeroed(l);if !p.is_null(){add(l.size());}p}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l);LIVE.fetch_sub(l.size(),Ordering::Relaxed);}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let q=System.realloc(p,l,n);if !q.is_null(){LIVE.fetch_sub(l.size(),Ordering::Relaxed);add(n);}q}
}
#[global_allocator] static ALLOCATOR:Counted=Counted;
#[repr(C)] #[derive(Default)] struct MallocStats {blocks_in_use:u32,size_in_use:usize,max_size_in_use:usize,size_allocated:usize}
extern "C" {fn malloc_zone_statistics(zone:*mut std::ffi::c_void,stats:*mut MallocStats);}
static DONE:AtomicBool=AtomicBool::new(false);
static PHASE:AtomicUsize=AtomicUsize::new(0);
fn report(label:&str,ordinal:usize,started:Instant){let mem=ProcessMemorySnapshot::capture().unwrap();let mut malloc=MallocStats::default();unsafe{malloc_zone_statistics(std::ptr::null_mut(),&mut malloc);}println!("phase={label} ordinal={ordinal} resident_bytes={} resident_peak={} rust_live={} rust_peak={} malloc_live={} malloc_allocated={} malloc_blocks={} elapsed_millis={}",mem.resident_bytes,mem.peak_resident_bytes,LIVE.load(Ordering::Relaxed),PEAK.load(Ordering::Relaxed),malloc.size_in_use,malloc.size_allocated,malloc.blocks_in_use,started.elapsed().as_millis());}
fn options()->SearchOutOfCoreGenerationBuildOptions{SearchOutOfCoreGenerationBuildOptions{lexical_build_memory_bytes:NonZeroU64::new(8*1024*1024).unwrap(),max_segment_uncompressed_bytes:NonZeroU64::new(64*1024*1024).unwrap(),..Default::default()}}
fn task()->RuntimeTaskContext{RuntimeTaskContext::default().with_memory_reservation(RuntimeMemoryReservation::new(256*1024*1024,0))}
fn embedding(ordinal:usize)->Option<Vec<f32>>{Some((0..384).map(|col|{let mut n=(ordinal as u64).wrapping_mul(0x9e3779b97f4a7c15).wrapping_add(col);n=(n^(n>>30)).wrapping_mul(0xbf58476d1ce4e5b9);n=(n^(n>>27)).wrapping_mul(0x94d049bb133111eb);n^=n>>31;(n>>40) as f32/8388608.0-1.0}).collect())}
fn metadata()->BTreeMap<String,String>{BTreeMap::from([("kind".into(),"memory".into()),("space_id".into(),"default".into())])}
fn row(n:usize,body:&str)->SearchProjectionRow{SearchProjectionRow{kind:SearchProjectionKind::Memory,external_id:format!("{:016x}",n*2),title:format!("Document {n}"),body:body.into(),embedding:embedding(n),source_id:None,metadata:metadata()}}
fn main(){let mut args=std::env::args().skip(1);let count:usize=args.next().unwrap().parse().unwrap();let saved=args.next();let root=saved.as_ref().map(PathBuf::from).unwrap_or_else(||PathBuf::from(format!("/private/tmp/hawdb-291-fresh-memory-phase-fixture-{}",SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos())));let _fd=hawdb_storage::file_descriptors::ProjectFileDescriptors::acquire(&root,1024).unwrap();let started=Instant::now();println!("fixture={} documents={count} body_bytes=65536 dimension=384 budget=268435456 saved_initial={}",root.display(),saved.is_some());report("before_build",0,started);
let observer=std::thread::spawn(move||{while !DONE.load(Ordering::Relaxed){std::thread::sleep(std::time::Duration::from_secs(5));if !DONE.load(Ordering::Relaxed){report("timer",PHASE.load(Ordering::Relaxed),started);}}});
let mut body="bounded-search-mutation ".repeat(65536/24+1);body.truncate(65536);
if saved.is_none(){let mut w=SearchOutOfCoreGenerationWriter::create_with_context(&root,options(),task()).unwrap();for n in 0..count {w.push(SearchDocument{id:format!("memory:{:016x}",n*2),title:format!("Document {n}"),content:body.clone(),embedding:embedding(n),metadata:metadata()}).unwrap();if n%8192==0{report("pushed",n,started);}}report("before_finish",count,started);PHASE.store(1,Ordering::Relaxed);let build=w.finish().unwrap();assert_eq!(build.document_count,count);println!("initial_artifacts={} document_payload={} vectors={} lexical={} rabitq={}",build.generation_bytes,build.document_payload_bytes,build.vector_payload_bytes,build.lexical_artifact_bytes,build.rabitq_artifact_bytes);report("after_finish",count,started);}
PHASE.store(2,Ordering::Relaxed);let mut reader=SearchOutOfCoreReader::open(&root).unwrap();assert_eq!(reader.document_count(),count);assert_eq!(reader.generation(),1);report("after_initial_open",0,started);
for seed in 0..32{PHASE.store(seed+3,Ordering::Relaxed);let u=SearchOutOfCoreGenerationWriter::prepare_delta_with_context(&reader,SearchProjectionDelta{upserts:vec![row(count+seed,&body)],..Default::default()},options(),task()).unwrap();report("seed_prepared",seed,started);let(_,b,_)=u.finish().unwrap();assert!(!b.cleanup_retry_required);report("seed_finished",seed,started);drop(reader);report("seed_reader_dropped",seed,started);reader=SearchOutOfCoreReader::open(&root).unwrap();assert_eq!(reader.document_count(),count+seed+1);report("seed_reopened",seed,started);}
PHASE.store(100,Ordering::Relaxed);let upserts=(0..10).map(|n|{let mut r=row(n,&body);r.title=format!("Updated document {n}");r.body.push_str(" changed");r.embedding=embedding(count+n);r}).collect();let u=SearchOutOfCoreGenerationWriter::prepare_delta_with_context(&reader,SearchProjectionDelta{upserts,..Default::default()},options(),task()).unwrap();report("K10_prepared",10,started);let(_,b,_)=u.finish().unwrap();assert!(!b.cleanup_retry_required);report("K10_finished",10,started);reader.refresh().unwrap();report("K10_refreshed",10,started);drop(reader);report("final_reader_dropped",10,started);DONE.store(true,Ordering::Relaxed);observer.join().unwrap();println!("diagnostic_complete fixture={}",root.display());}

